# area: self_classmethods
# hypothesis: Self-typed fluent methods and a classmethod alternative constructor keep the HtmlBuilder subclass type through a method chain, and CPython builds the same subclass instance.
from typing import Self, assert_type, reveal_type


class Builder:
    def __init__(self) -> None:
        self.parts: list[str] = []

    def add(self, part: str) -> Self:
        self.parts.append(part)
        return self

    @classmethod
    def from_parts(cls, *parts: str) -> Self:
        b = cls()
        for p in parts:
            b.add(p)
        return b

    def build(self) -> str:
        return '-'.join(self.parts)


class HtmlBuilder(Builder):
    def tag(self, name: str) -> Self:
        return self.add(f'<{name}>')


hb = HtmlBuilder.from_parts('a', 'b').tag('p').add('x')
assert_type(hb, HtmlBuilder)
reveal_type(hb)
assert isinstance(hb, HtmlBuilder)
assert hb.build() == 'a-b-<p>-x'
assert Builder().add('z').build() == 'z'
